function predictionArtwork(){return `<svg class="ai-rate-art" width="120" height="120" viewBox="0 0 120 120" fill="none" aria-hidden="true"><defs><linearGradient id="ai-orbit" x1="10" y1="40" x2="110" y2="80" gradientUnits="userSpaceOnUse"><stop stop-color="#003cff"/><stop offset=".5" stop-color="#3699ee"/><stop offset="1" stop-color="#76f5e9"/></linearGradient></defs><ellipse cx="60" cy="60" rx="52" ry="26" stroke="url(#ai-orbit)" stroke-width="4"/><ellipse cx="60" cy="60" rx="52" ry="26" transform="rotate(90 60 60)" stroke="url(#ai-orbit)" stroke-width="4"/></svg><span class="ai-rate-art-star" aria-hidden="true"></span>`;}
function scatterChart(){
 // Only visible sample points from the supplied reference; red marks omitted.
 const points=[[18,166],[22,180],[29,166],[31,181],[39,45],[47,130],[48,198],[52,164],[78,59],[95,52],[105,109],[112,187],[113,54],[125,102],[132,53],[137,49],[149,172],[151,186],[165,73],[168,104],[176,174],[184,151],[185,196],[190,120],[200,103],[210,101],[218,121],[219,150],[220,166],[221,183],[225,201],[230,155],[231,114],[232,99],[234,55],[237,58],[239,72],[240,91],[241,103],[241,131],[242,155],[242,164],[244,180],[245,197],[239,202]];
 return `<svg class="ai-rate-chart" viewBox="0 0 320 280" role="img" aria-label="나와 비슷한 사람들이 받은 대출 분포 예시"><text x="0" y="15" class="chart-muted">한도(만원)</text>${[[32,'1,200'],[92,'1,030'],[152,'870'],[212,'700']].map(([y,label])=>`<text x="0" y="${y+4}">${label}</text><line x1="64" y1="${y}" x2="312" y2="${y}" stroke="#e4e6ed" stroke-dasharray="2 2"/>`).join('')}${points.map(([x,y])=>`<circle cx="${x+64}" cy="${y}" r="3.2" fill="#da5fe9" opacity=".85"/>`).join('')}<line x1="64" y1="228" x2="312" y2="228" stroke="#949bb0"/>${[[64,'10.7'],[147,'10.9'],[229,'11.1'],[312,'11.3']].map(([x,label])=>`<text x="${x}" y="248" text-anchor="middle">${label}</text>`).join('')}<text x="312" y="268" text-anchor="end" class="chart-muted">금리(%)</text></svg>`;
}
export function aiRateScreen(){return `<div class="ai-rate-screen"><header class="ai-rate-top"><button type="button" class="ai-rate-back" data-action="ai-rate-back" aria-label="홈으로 돌아가기">‹</button></header><div class="ai-rate-scroll"><section class="ai-rate-overview"><div class="ai-rate-notice"><span aria-hidden="true">i</span><p>매일 오전 7시에 최신 조건으로 바뀌어요.</p></div><div class="ai-rate-artwork">${predictionArtwork()}</div><h2>오늘 OOO님의<br>신용대출 AI 예상조건</h2><button type="button" class="ai-rate-explain" disabled>예측은 어떻게 이루어지나요? <span>›</span></button><div class="ai-rate-values"><div><p>내 예상 금리</p><strong>—<span>%</span></strong></div><div><p>내 예상 한도</p><strong>—<span>만원</span></strong></div></div><section class="ai-rate-policy"><h3><span aria-hidden="true">🎉</span> 정책상품 대상자예요!</h3><div class="ai-rate-values"><div><p>정책상품 금리</p><strong>—<span>%</span></strong></div><div><p>정책상품 한도</p><strong>—<span>만원</span></strong></div></div></section></section><section class="ai-rate-distribution"><h2>최근 한달간 나와 비슷한 사람들이 <span class="ai-rate-help" aria-hidden="true">?</span><br>실제로 받은 대출 분포예요</h2><p>내 예측 결과를 검증할 수 있는 데이터예요.</p>${scatterChart()}</section><section class="ai-rate-comparisons"><h2>나와 비슷한 사람들이 실제로 받은<br>금리·한도 조건이에요</h2><div class="ai-rate-tabs" role="tablist" aria-label="대출 조건 정렬"><button type="button" role="tab" aria-selected="true" data-ai-sort="rate">금리 낮은 순</button><button type="button" role="tab" aria-selected="false" data-ai-sort="limit">한도 높은 순</button></div><div class="ai-rate-offers">${[7,14,8].map((day,i)=>`<div class="ai-rate-offer"><div class="ai-rate-bank ${i===2?'blue':''}" aria-hidden="true">${i===2?'S':'a'}</div><div class="ai-rate-product"><strong>${i===2?'신한카드':'•••• 은행'}</strong><p>•••••• 대출</p><span class="ai-rate-badge">핀다입점상품</span></div><div class="ai-rate-terms"><strong>•••%</strong><b>•••만원</b><small>${day}일 전 실행된 대출</small></div><span class="ai-rate-chevron" aria-hidden="true">›</span></div>`).join('')}</div></section><section class="ai-rate-update"><button type="button" disabled>내 대출 정보 최신으로 업데이트 하기 <span>›</span></button></section></div><footer class="ai-rate-footer"><button type="button" class="primary" disabled>한도조회 해보기</button></footer></div>`;}
export function wireAiRate(root){
 for(const button of root.querySelectorAll('[data-ai-sort]'))button.addEventListener('click',()=>{
  for(const tab of root.querySelectorAll('[data-ai-sort]'))tab.setAttribute('aria-selected',String(tab===button));
 });
}
